1	/**
2	 * Renders a react-email component to the `{ subject, html, text }` triple
3	 * `EmailService` sends.
4	 *
5	 * `EmailTemplate` is the closed vocabulary of templates; this module is the
6	 * only place that maps a name to a component and to a subject line, so
7	 * adding a template means touching exactly one switch in each direction.
8	 */
9	import { render } from "@react-email/components";
10	import { createElement, type ReactElement } from "react";
11	import { SITE_CONFIG } from "@/config/site";
12	import type {
13	  EmailTemplate,
14	  RenderedEmail,
15	} from "@/server/services/email-service";
16	import { DigestEmail, type DigestEmailProps } from "./digest-email";
17	import { InviteEmail, type InviteEmailProps } from "./invite-email";
18	import { InvoiceEmail, type InvoiceEmailProps } from "./invoice-email";
19	import { MentionEmail, type MentionEmailProps } from "./mention-email";
20	import { OverdueEmail, type OverdueEmailProps } from "./overdue-email";
21	import {
22	  PasswordResetEmail,
23	  type PasswordResetEmailProps,
24	} from "./password-reset-email";
25	import { WelcomeEmail, type WelcomeEmailProps } from "./welcome-email";
26	
27	type Props = Readonly<Record<string, unknown>>;
28	
29	/** Reads a string prop defensively — templates are fed loosely typed payloads. */
30	function str(props: Props, key: string, fallback = ""): string {
31	  const value = props[key];
32	  return typeof value === "string" && value !== "" ? value : fallback;
33	}
34	
35	function count(props: Props, key: string): number {
36	  const value = props[key];
37	  return Array.isArray(value) ? value.length : 0;
38	}
39	
40	function elementFor(template: EmailTemplate, props: Props): ReactElement {
41	  switch (template) {
42	    case "invite":
43	      return createElement(InviteEmail, props as unknown as InviteEmailProps);
44	    case "digest":
45	      return createElement(DigestEmail, props as unknown as DigestEmailProps);
46	    case "mention":
47	      return createElement(MentionEmail, props as unknown as MentionEmailProps);
48	    case "invoice":
49	      return createElement(InvoiceEmail, props as unknown as InvoiceEmailProps);
50	    case "welcome":
51	      return createElement(WelcomeEmail, props as unknown as WelcomeEmailProps);
52	    case "password-reset":
53	      return createElement(
54	        PasswordResetEmail,
55	        props as unknown as PasswordResetEmailProps,
56	      );
57	    case "overdue":
58	      return createElement(OverdueEmail, props as unknown as OverdueEmailProps);
59	  }
60	}
61	
62	/** The subject line for a template, derived from the same props as the body. */
63	export function subjectFor(template: EmailTemplate, props: Props): string {
64	  switch (template) {
65	    case "invite":
66	      return `${str(props, "inviterName", "Someone")} invited you to ${str(
67	        props,
68	        "orgName",
69	        SITE_CONFIG.name,
70	      )}`;
71	    case "digest": {
72	      const total = count(props, "entries");
73	      return `Your ${str(props, "orgName", SITE_CONFIG.name)} digest — ${total} update${
74	        total === 1 ? "" : "s"
75	      }`;
